cat > packs/claude-code-web-users-support/session-prepare.mjs <<'PREPEOF'
// This pack's session-prepare step: pour the pack belonging to the person in front of
// this session into the session's own pack root, before anything reads the pack set.
//
// WHY A WHOLE PACK AND NOT A FILE. What a person wants a session to know is not only
// prose. It is a skill they reach for, a check that catches the mistake they keep making,
// a requirement their tooling needs installed. Every one of those already has a carrier —
// the pack — with an engine that mounts, runs and reports it. Pouring a pack gets all of
// them at once; the file this step replaced could only ever carry the first.
//
// WHY PREPARE AND NOT START. The skill mount and the self-test read the session's pack
// set before session-start.mjs runs. A pack that arrives after them is a pack whose
// skills are not mounted and whose absence was never judged, so the pour has to happen in
// the phase that runs first (engine/pack_loader/run-pack-session-start.mjs).
//
// WHY THE CONTENT IS NOT HERE. It belongs to a person, not to a project and not to the
// shared canon — which every fleet mounts, and which is therefore both the wrong host for
// one group's people and the wrong authority on where they live. So this pack carries the
// ADDRESS (its entry `config`, read via store.mjs) and the group carries the content.
//
// LOCAL FIRST. When this tree IS the store, the working copy is what the owner is reading
// and editing — a fetch would serve the default branch and quietly hide the edit in
// progress.
//
// ATTENDED SESSIONS ONLY. A routine fired under a person's account carries their identity
// but not their presence, and a pack written for a present person (a popup for every
// decision, a callout closing every turn) misdirects a run nobody is watching. The harness
// says which it is in CLAUDE_CODE_SESSION_ATTENDED; only an explicit "not attended"
// declines, so an older harness that never sets it still pours.
//
// FAIL-SOFT ON EVERY MISS, and SILENT HERE. No identity, no configured store, no pack, a
// fetch that fails: the pour leaves an empty pack behind and writes what happened to the
// receipt, which session-start.mjs turns into the one note a reader sees. Nothing in this
// file is load-bearing — the packs, checks and skills a session needs are already local.
//
// WHAT IT WILL WRITE, and nothing else: Markdown, JavaScript modules and JSON, under one
// directory, within a file count and byte budget. A pack is executable code that will run
// inside this session's hooks, so the store repo is as trusted as the repository itself —
// stated in the pack's README, because no cap here can substitute for that.

import { existsSync, mkdirSync, readFileSync, writeFileSync, rmSync, readdirSync, statSync } from 'node:fs';
import { join, dirname, relative, sep } from 'node:path';
import { resolveStore, folderFor, legacyFileFor, isUsableIdentity } from './store.mjs';

const FETCH_TIMEOUT_MS = 15_000;
const FETCH_ATTEMPTS = 3;

// The budget a person's pack is poured within. Generous for what a pack is, small enough
// that a mistake in the store cannot fill a session's disk or its context.
const MAX_FILES = 60;
const MAX_BYTES = 512 * 1024;
const POURABLE = /\.(md|mjs|json)$/;

// Where the session's pack root and this pack's directory inside it sit. The engine owns
// both names (engine/pack_loader/pack-registry.mjs); they are spelled here rather than
// imported because a member's vendored engine may predate them, and a step that fails to
// import is a step that never ran.
const PACK_ROOT = join('.claudinite', 'temp', 'packs');
const PACK_DIR = join(PACK_ROOT, 'current_user');
const RECEIPT = '.pour.json';

const root = process.env.CLAUDE_PROJECT_DIR || process.cwd();
const dest = join(root, PACK_DIR);

// What happened, for session-start.mjs to say. Written last and always: a session where
// this file is absent is a session where the step itself did not run, which is a different
// thing from a pour that found nothing.
function finish(receipt) {
  try {
    mkdirSync(dest, { recursive: true });
    if (!existsSync(join(dest, 'RULES.md'))) {
      writeFileSync(join(dest, 'RULES.md'), '<!-- No personal pack was poured into this session. -->\n');
    }
    writeFileSync(join(dest, RECEIPT), `${JSON.stringify(receipt, null, 2)}\n`);
  } catch (e) {
    process.stderr.write(`could not write the poured pack: ${e.message}\n`);
  }
  process.exit(0);
}

// The manifest the poured pack runs under when the person's own directory carries none —
// which is the ordinary case, because a person with rules to state should not have to
// write a manifest to state them. Their own pack.mjs is poured untouched when they have
// one; it must leave `id` unset, since the engine takes a poured pack's id from its
// directory and this directory is the session's.
const SYNTHESIZED_MANIFEST = `// GENERATED by claude-code-web-users-support: the manifest the person's own pack
// directory did not carry. Edit nothing here — it is rewritten every session.
export default {
  version: '0.0.0',
  ruleRoutingGuidance: {
    belongs: 'how this person wants to be worked with, in every project they work in',
    excludes: 'a project\\'s own conventions — those belong to the packs that own each subject',
  },
};
`;

// Empty the directory before pouring: a pack left by an earlier session, for an earlier
// person or an earlier version of this one's, is content nobody chose. The root is the
// engine's session state and this pack's own subdirectory within it, so nothing tracked
// is ever at risk.
function reset() {
  try { rmSync(dest, { recursive: true, force: true }); } catch { /* an unwritable temp root fails at the write below */ }
  mkdirSync(dest, { recursive: true });
}

// One poured file, path-checked against the destination it claims to sit in.
function pour(relPath, content) {
  const target = join(dest, relPath);
  const inside = relative(dest, target);
  if (inside.startsWith('..') || inside.startsWith(sep) || inside === '') return false;
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, content);
  return true;
}

const config = (() => {
  try { return JSON.parse(process.env.CLAUDINITE_PACK_CONFIG || '{}'); } catch { return {}; }
})();

const store = resolveStore(config);
if (!store) finish({ outcome: 'no-store' });
if (process.env.CLAUDE_CODE_SESSION_ATTENDED === '0') finish({ outcome: 'unattended' });

const email = process.env.CLAUDE_CODE_USER_EMAIL || '';
if (!email) finish({ outcome: 'no-identity' });
if (!isUsableIdentity(email)) finish({ outcome: 'unusable-identity', identity: String(email).replace(/["\\]/g, '') });

const folder = folderFor(store, email);
const legacy = legacyFileFor(store, email);

// Every file under a directory in this tree, as store-relative paths.
function localFiles(absDir, prefix) {
  const out = [];
  for (const entry of readdirSync(absDir, { withFileTypes: true })) {
    const rel = `${prefix}/${entry.name}`;
    if (entry.isDirectory()) out.push(...localFiles(join(absDir, entry.name), rel));
    else if (entry.isFile()) out.push(rel);
  }
  return out;
}

// The store's file list and a reader for one file, from whichever side has it. Local
// first; otherwise the repository's git tree in one call, and each file over raw, which is
// the same host and the same anonymous read the single-file fetch used before.
async function source() {
  const localDir = join(root, folder);
  if (existsSync(localDir) && statSync(localDir).isDirectory()) {
    return {
      where: 'working tree',
      files: localFiles(localDir, '').map((p) => p.slice(1)),
      read: async (p) => readFileSync(join(localDir, p)),
    };
  }
  const localLegacy = join(root, legacy);
