import { finding } from '../../../engine/checks/helpers/findings.mjs';
import { resolveStore, isUsableIdentity } from '../store.mjs';
// A namespace import, guarded in `run`: the pack and engine lanes deliver on separate
// cadences, and a member whose engine predates the helper must load this pack rather
// than fault on a missing named export.
import * as provenance from '../../../engine/checks/helpers/provenance.mjs';

// A person's preferences are a pack of one reader (the provenance design, #2136): each
// preference is an element, and its file sits BESIDE the store, under
// `<path>-provenance/<email>/`, because the store's own check keeps `<path>/` flat and
// addresses nothing there but `<email>.md`. This check asserts existence only - every
// preference bullet ends with a marker naming a file under that folder - and shares no
// logic with the growth pack beyond the engine's own bullet reader: the grammar of the
// file is judged by the growth tool's `check`, run by the session that edits the
// preference.
//
// ADVISORY, like everything in this pack: the loss is a missing why for a preference,
// never a broken repo. RELEVANCE-FIRST like its siblings: inert unless this repo IS the
// store - only the one repo that holds `<path>/<email>.md` files has anything to judge.
const PACK = 'claude-code-web-users-support';

export const provenanceDirOf = (store) => `${store.path}-provenance`;

const rule = {
  id: 'preferences-provenance',
  severity: 'advisory',
  description: 'Every preference in a store this repo holds ends with a marker naming its provenance file beside the store',
  doc: 'packs/claude-code-web-users-support/RULES.md',
  why: 'a preference with no file has no record of when it was set or what prompted it, and the session that changes it next is the only reader who could have written that down',

  run(ctx) {
    if (typeof provenance.ruleBlocks !== 'function') return []; // an engine that predates the helper
    const { ruleBlocks } = provenance;
    const store = resolveStore(ctx.config.packConfig?.[PACK] ?? null);
    if (!store) return [];
    const prefix = `${store.path}/`;
    const held = (ctx.files ?? []).filter((f) => f.startsWith(prefix) && !f.slice(prefix.length).includes('/') && f.endsWith('.md') && f !== `${prefix}README.md`);
    if (!held.length) return [];
    const out = [];
    for (const file of held) {
      const email = file.slice(prefix.length, -3);
      if (!isUsableIdentity(email)) continue; // store-file-names reports the name
      const dir = `${provenanceDirOf(store)}/${email}`;
      for (const b of ruleBlocks(ctx.read(file) ?? '')) {
        if (!b.slug) {
          out.push(finding(rule, {
            file, line: b.start + 1,
            what: `the preference "${b.trigger}" ends with no marker naming its provenance file`,
            fix: `end it with a slug marker, e.g. (${b.trigger.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').split('-').slice(0, 3).join('-')}), and write that file under ${dir}/ with a born entry saying when the preference was set and what prompted it`,
          }));
        } else if (!ctx.exists(`${dir}/${b.slug}.md`)) {
          out.push(finding(rule, {
            file, line: b.lastLine + 1,
            what: `the preference "${b.trigger}" names ${dir}/${b.slug}.md, which does not exist`,
            fix: `create ${dir}/${b.slug}.md with a born entry, or fix the marker to the file it meant`,
          }));
        }
      }
    }
    return out;
===== CONFIGURED
import { finding } from '../../../engine/checks/helpers/findings.mjs';
import { resolveStore } from '../store.mjs';

// Declaring this pack is a statement that this project's users HAVE a preferences
// store. If its entry names none — or names one that does not resolve — the pack is
// wired up and silently inert: every session reads its fail-soft note instead of
// anyone's preferences, and nothing else ever says so.
//
// ADVISORY, not blocking. The failure is a lost nicety, never a broken repo: no
// check, no task and no other pack depends on the store being reachable, and a
// project mid-adoption (declared, interview not yet answered) is in exactly this
// state legitimately for a while. It is a nudge with the fix in it.
const rule = {
  id: 'preferences-store-configured',
  severity: 'advisory',
  description: 'A declared claude-code-web-users-support pack names a store its session-start step can read',
  doc: 'packs/claude-code-web-users-support/RULES.md',
  why: 'a declared pack with no store injects nobody\'s preferences and says so only in a fail-soft note nobody reads twice',

  run(ctx) {
    // The pack's own entry config, through the engine's normalized per-pack view.
    const config = ctx.config.packConfig?.['claude-code-web-users-support'];
    if (resolveStore(config ?? null)) return [];
    return [finding(rule, {
      file: '.claudinite-settings.json',
      what: config === undefined
        ? 'the claude-code-web-users-support pack is declared but names no store'
        : `the claude-code-web-users-support pack's store does not resolve (${JSON.stringify(config)})`,
      fix: 'give the pack entry a "config": { "repo": "owner/name" } naming the repo that holds this project\'s users\' preferences — "path" is optional and defaults to preferences/',
    })];
  },
};

export default rule;
===== RULES
# claude-code-web-users-support — working from Claude Code on the web

- **A person asking to change one of their personal preferences** — edit their `<email>.md` in the
  preferences store repo this pack names, never here and never in the canon, and append the
  entry on the preference's provenance file beside the store (`<path>-provenance/<email>/`),
  the person the actor; a project convention in disguise belongs in the pack owning its
  subject, and a preference triggering a command owns only the trigger phrase.
  (person-asking-change)

- **A person asking to record their personal preferences with no file yet** — create it in that
  store repo, named for their exact identity plus `.md`, case included: the reader opens
  `<path>/<email>.md` and nothing else, so any other name is silently never read.
  (person-asking-record)

- **A web session halt-gated on a missing toolchain requirement** — re-paste
  [`environment-setup-command.sh`](environment-setup-command.sh) whole and unedited into the
  environment's Setup script field, then rebuild; a project-specific step belongs in its own
  pack's `env` declaration, never in that body. (web-session-halt)

