pour_head = '''// Pouring a person's pack into the session: the mechanics, as one function two callers
// share. `session-prepare.mjs` calls it in the phase before the session's pack set is
// read, which is where it belongs; `session-start.mjs` calls it only when that phase did
// not run at all, which is what a member holding this pack beside an older engine has.
// The two lanes deliver on separate cycles, so that window is ordinary rather than
// exceptional, and the difference for the person in it is that their skills are not
// mounted — never that their rules are missing.
//
// WHAT IT WILL WRITE, and nothing else: Markdown, JavaScript modules and JSON, under one
// directory, within a file count and byte budget. A pack is executable code that will run
// inside this session's hooks, so the store repo is as trusted as the repository itself —
// stated in the pack's README, because no cap here can substitute for that.

'''
body = body.replace("""const root = process.env.CLAUDE_PROJECT_DIR || process.cwd();
const dest = join(root, PACK_DIR);

// What happened, for session-start.mjs to say. Written last and always: a session where
// this file is absent is a session where the step itself did not run, which is a different
// thing from a pour that found nothing.
function finish(receipt) {
  try {
    mkdirSync(dest, { recursive: true });
    if (!existsSync(join(dest, 'RULES.md'))) {
      writeFileSync(join(dest, 'RULES.md'), '<!-- No personal pack was poured into this session. -->\\n');
    }
    writeFileSync(join(dest, RECEIPT), `${JSON.stringify(receipt, null, 2)}\\n`);
  } catch (e) {
    process.stderr.write(`could not write the poured pack: ${e.message}\\n`);
  }
  process.exit(0);
}
""", """// Where the pour writes, and where a reader looks for what it left.
export const packDirIn = (root) => join(root, PACK_DIR);
export const receiptIn = (root) => join(packDirIn(root), RECEIPT);
""")
open('packs/claude-code-web-users-support/pour.mjs','w').write(pour_head + body)
print('split written')
