  const root = project();
  try {
    storeHere(root, { 'RULES.md': '  \n\n \t\n' });
    run(PREPARE, root, { config: { repo: 'owner/store' } });
    const r = run(START, root, { config: { repo: 'owner/store' } });
    assert.equal(r.status, 0);
